    R.boat = kind === 'paddle' ? pb : boats[dockOf.indexOf(i)]; R.pts = path(kind, i); R.seg = []; R.len = 0;
    for (let k = 1; k < R.pts.length; k++) { const l = Math.hypot(R.pts[k][0] - R.pts[k - 1][0], R.pts[k][1] - R.pts[k - 1][1]); R.seg.push(l); R.len += l; }
