    const L = LANDMARKS.find((l) => l.id === 'aquarium'), lines = L && L.boss && L.boss.lines;
    DUELS.banner('BIG JIMMY<small>NATIONAL AQUARIUM · THE BIG TANK</small>', 2.4);
