    { const H = K(); H.add(G.box(1.4, 0.86, 0.08), TE, 0, -0.43, 0).add(G.box(1.0, 0.1, 0.1), LI, 0, -0.43, 0.05); H.mesh(mM, R.hatch, 0); }
    // shoulder shakers (the seasoning cloud): two mesh-merged shakers on a yoke that tips forward
