    R.arms.forEach((a, i) => { a.sh.rotation.x = damp(a.sh.rotation.x, armsT[i][0] + C.fl * 0.5, 14, dt); a.sh.rotation.y = damp(a.sh.rotation.y, armsT[i][1], 14, dt); });
