      g.fillStyle = '#ffd890'; g.fillRect(x + 22, 228, sw - 44, 150); // lit stall window
      g.fillStyle = 'rgba(120,70,30,.5)'; for (let k = 0; k < 4; k++) g.fillRect(x + 30 + k * (sw - 60) / 4, 300, (sw - 60) / 4 - 10, 70);
