        for (let l = 0; l < 4; l++) k.add(G.cyl(0.115 - l * 0.004, 0.12, 0.022, 10), l % 2 ? '#a8505a' : '#c87070', x + (l % 2 ? 0.01 : -0.01), 0.065 + l * 0.022, z, 0, l, 0.08 * (l % 2 ? 1 : -1));
