        const d = dS(st.s, pig.s); pig.s = wrapS(pig.s + clamp(d, -4.2 * dt, 4.2 * dt)); onWall(pig.s, 0.5); pig.pos.set(_w.x, ROOFY, _w.z); pig.yaw = Math.atan2(_w.nx, _w.nz);
