    S2.forEach((p, i) => { M4.compose(p.p, q, ONE); P.sparkM.setMatrixAt(i, M4); }); P.sparkM.count = S2.length; P.sparkM.visible = S2.length > 0; P.sparkM.instanceMatrix.needsUpdate = true;
