    mm.root.rotation.y = M.tgt ? Math.atan2(M.tgt.p.x - M.x, M.tgt.p.z - M.z) : st.part === 1 ? Math.atan2(-M.x, -M.z) : Math.atan2(st.pig.pos.x - M.x, st.pig.pos.z - M.z); applyPose(mm, mavisPose(st, t), 12, dt, false);
