    k.add(G.cyl(0.035, 0.035, 1.7, 6), col, 0, 0, 0).add(G.tor(0.2, 0.025, 6, 14), '#e8e4d8', 0, 0.98, 0, 0, Math.PI / 2, 0, 1, 1.25, 1).add(G.sph(0.17, 8, 5), '#d8d4c8', 0, 0.9, 0, 0, 0, 0, 0.2, 1.1, 1);
