          if (st.inv <= 0) { st.hp -= DMG.tumble; st.stats.hitsTaken++; st.stats.hits.tumble++; DUELS.hurt(); sfx('hurt'); if (st.hp <= 0) { st.inv = 0; st.hp = 1; hurtHarold(st, 1, 'tumble'); } }
