    P.fxs.forEach((p, i) => { const s = 1 - p.t / p.life * 0.6; M4.compose(p.p, q, V.set(s, s, s)); P.fx.setMatrixAt(i, M4); }); P.fx.count = P.fxs.length; P.fx.visible = P.fxs.length > 0; P.fx.instanceMatrix.needsUpdate = true;
