    if (st.hurtT > 0) return HERO_POSES.hurt(1 - st.hurtT / 0.4);
    if (st.atkT >= 0) { const c = COMBO[st.atkI]; return HERO_POSES[c.pose](clamp(st.atkT / c.t, 0, 1)); }
    if (st.hy > 0.02) return HERO_POSES.jump(st.vy);
