    P.bang.visible = tell; if (tell) { P.bang.position.set(st.qx, HT + 4.6 + Math.sin(st.t * 10) * 0.08, st.qz); const s = 1 + 0.15 * Math.sin(st.t * 18); P.bang.scale.set(0.55 * s, 1.1 * s, 1); }
