    if (st.ms === 'shoveTell') { const k = clamp(st.mt / st.mdur, 0, 1); ringAt(st.qx, st.qz, 1.2 + 1.8 * k, new THREE.Color('#ff2a3a').multiplyScalar(pulse), HT); }
