    if (st.salT >= 0 || (st.ms === 'stun' && st.sal0)) { const k = st.salT >= 0 ? clamp(st.salT / 1.0, 0, 1) : 1; mx = lerp(st.sal0.mx, st.qx + 0.9, ease(k)); mz = lerp(st.sal0.mz, st.qz - 0.9, ease(k)); myaw = Math.atan2(st.qx - mx, st.qz - mz); }
