    R.add(G.cyl(0.18, 0.18, 22, 8), '#6a6e74', -12.4, 0.5, 1.5, Math.PI / 2, 0, 0).add(G.cyl(0.12, 0.12, 22, 8), '#8a6a4a', -12.4, 0.85, 1.5, Math.PI / 2, 0, 0);
