    g.strokeStyle = 'rgba(255,255,255,.55)'; g.lineWidth = 6; g.beginPath(); g.arc(w / 2, h / 2, 90, 0, TAU); g.stroke(); g.strokeRect(14, 14, w - 28, h - 28);
