    const yaw = Math.atan2(st.bx - st.hx, st.bz - st.hz); for (let k = 0; k < 4; k++) { const a = yaw + (n === 1 ? -1 : 1) * (k - 1.5) * 0.35; burst(V.set(st.hx + Math.sin(a) * 1.0, n === 2 ? 1.8 - k * 0.3 : 1.0, st.hz + Math.cos(a) * 1.0), 1, ['#1fd1c1', '#b8fff6'], 0.6, 0.35, 0.5); }
