      const n = st.stats.taken, grade = n <= 3 ? 'S' : n <= 8 ? 'A' : 'B', stars = grade === 'S' ? 3 : grade === 'A' ? 2 : 1; st.grade = grade; DUELS.log.push('compking:win:' + grade);
