    R.arm = new THREE.Group(); R.arm.position.set(0.4, 1.15, 0); R.root.add(R.arm);
    { const A = K(); A.add(G.cyl(0.07, 0.06, 0.6, 6), '#3f8f8a', 0, -0.3, 0).add(G.sph(0.1, 6, 5), '#3f8f8a', 0, -0.62, 0); A.mesh(M, R.arm, 0.003); }
