    if (R.update) { try { R.update(dt, st.ms, { t, u, lane: st.ms === 'shell' || st.ms === 'shellTell' ? st.cross[st.crossI] : st.safe, phase: st.phase }); } catch (e) { console.error(e); R.update = null; } return; }
