    for (let k = 0; k < 8; k++) { const a = k / 8 * TAU; R.add(G.cyl(0.03, 0.03, 1.5, 4), '#6a4a2a', 2.9 + Math.cos(a) * 0.05, 1.9 + Math.sin(a) * 0.05, 11.0, 0, 0, a); }
    // the belfry (screen right of the captain) — the bell itself swings (separate mesh)
