    // props: Mavis's purse (HAIL MAVIS), the fumbled cane
    S.purse = purseMesh(); S.purse.visible = false; sc.add(S.purse); S.dropCane = caneMesh(); S.dropCane.visible = false; sc.add(S.dropCane);
