    S.fx.count = 0; S.fx.frustumCulled = false; S.fx.renderOrder = 8; for (let i = 0; i < 140; i++) S.fx.setColorAt(i, C3.set('#fff')); sc.add(S.fx); S.fxs = [];
    // Harold, Mavis, the Raven King
