    if (mode === 'swoop') { aLz = 1.8 + Math.sin(t * 20) * 0.4; aRz = -1.8 - Math.sin(t * 20) * 0.4; lean = 0.3; }
    if (mode === 'strut') { aLz = 0.4; aRz = -0.4; aLx = Math.sin(t * 9) * 0.4; aRx = -Math.sin(t * 9) * 0.4; roll = Math.sin(t * 9) * 0.08; hX = -0.2; }
