      S.swarmSh.visible = S.swarmRing.visible = A.t < A.tell + 0.3; S.swarmSh.position.set(A.tx, 0.03, A.tz); const s = lerp(1.4, 3.2, k); S.swarmSh.scale.set(s, s, 1); S.swarmSh.material.opacity = 0.2 + 0.4 * k;
