    F.ui.cm.style.width = (nxt ? clamp((save.chompy - (UPG[lv - 1] ? UPG[lv - 1].at : 0)) / (nxt.at - (UPG[lv - 1] ? UPG[lv - 1].at : 0)), 0, 1) * 100 : 100).toFixed(0) + '%';
