    let p = HERO_POSES.idle(t); legsStance(p, 0.14, 0.2); p.torso = [hold ? -0.2 : 0.05, 0, 0]; p.shR = [-1.3 + (st.ph === 'cast' ? -0.8 * Math.sin(cast * Math.PI) : 0) + (hold ? Math.sin(t * 9) * 0.05 : 0), 0, -0.1]; p.elR = [-0.5, 0, 0]; p.shL = [-1.0, 0, 0.25]; p.elL = [-1.0, 0, 0];
