    for (const s of STONES) { const t = clamp(((s[0] - ax) * dx + (s[1] - az) * dz) / l2, 0.05, 0.95), cx = ax + dx * t - s[0], cz = az + dz * t - s[1]; if (cx * cx + cz * cz < SR * SR) return true; }
